div#text-12 {
    height: 300px;
    overflow-x: hidden;
    overflow-y: scroll;
}body {
line-height: 1.5;
font-family: Proxima Nova, Arial, sans-serif;
font-size: 14px;
color: #525252;
background-color: #fff !important;
}

body, html, wrapper {
overflow-x: hidden;
}

body .top-menu {
float: none; 
margin:  0; 
padding: 0;
width: 100%;
background-color: #ddd;
text-align: right;
}


.post-entry a {
text-decoration: underline;
}


/* SPECIAL BANNER FOR NEW 2020 RESOURCES*/

div.tag-2020-resources .post-data {
    background-image: url(http://news.blogs.lib.lsu.edu/files/2020/03/newresource.png);
    background-repeat: no-repeat;
    height: 107px;
}

/*END OF NEW 2020 RESOURCES TAG IMAGE*/

/* SLIDER PLUGIN  */

 #nextend-smart-slider-2 .nextend-transition.nextend-transition-next .smartslider-inner {
    background-color: #FDD023 !important;
}

#nextend-smart-slider-2 .nextend-transition.nextend-transition-previous .smartslider-inner, #nextend-smart-slider-2 .nextend-transition.nextend-transition-next .smartslider-inner {
    background-color: #FDD023 !important;
}

#nextend-smart-slider-2 .nextend-bullet-container .nextend-bullet-numbers.nextend-bullet.active, #nextend-smart-slider-2 .nextend-bullet-container .nextend-bullet-numbers.nextend-bullet:HOVER {
    background: #FDD023 !important;
}

.nextend-transition-next-my-test .smartslider-outer, .nextend-transition-next-my-test .smartslider-inner {
    background-image: url(http://news.blogs.lib.lsu.edu/wp-content/plugins/smart-slider-2/plugins/nextendsliderwidgetarrow/transition/transition/next/my-test.png);
background-color:#464646 !important;
}

.nextend-transition-previous-my-test .smartslider-outer, .nextend-transition-previous-my-test .smartslider-inner {
    background-image: url(http://news.blogs.lib.lsu.edu/wp-content/plugins/smart-slider-2/plugins/nextendsliderwidgetarrow/transition/transition/previous/my-test.png);
background-color:#464646 !important;
}


#nextend-smart-slider-10 .nextend-bullet-container .nextend-bullet-numbers.nextend-bullet {
    background-color: #464646 !important;
}




/* END OF SLIDER PLUGIN */ 

.post-entry a, #widgets .textwidget a {
color: #461d7c !important;
}

#widgets {
    margin-top: -50px;
}


#author-meta {
/*display: none;
 doesn't work with custom byline plugin */
}



.blogtitle {
color: #461D7C; 
font-size: 43px;
font-weight: 600; 

}

.site-name {
display: none;
}

.site-description {
 visibility: hidden; 
}

.site-description {
color: #535353;
float: right;
margin: 50px 30px 0 0;
font-size: large;
}

#content, #content-blog, #content-full {
margin-top: 0px;
}

#header {
background: #ffffff ; /* Old browsers */


}

/* 3/16/18 */
#container {
max-width: 100%;
padding: 0px
}

#logo {
float: none;
/* width: 960px; */
margin: auto;
margin-left: 109px;
}

#wrapper {
width: 80%;
max-width: 1260px;
/* 3/16/18 */
margin-top: 52px;
}

#wrapper {
    -webkit-border-radius: 4px;
    -moz-border-radius: 4px;
    background-color: #fff;
    border: 1px solid #e5e5e5;
    border-radius: 4px;
    clear: both;
    margin: 18px auto;
    padding: 30px 20px 20px;
    position: relative;

}

/* this is a work around- the blog title option stopped working 12/2020 after a failed upgrade */

#wrapper:before {
  content: "News and Notes";
color: #461D7C; 
font-size: 43px;
font-weight: 600; 
}

ul#menu-categories {

/* padding-left: 171px;*/
}

.menu {
/* background-color: #616161;  5/18/18*/
background-color: transparent;
background-image: none;
margin-top:8px !important; /*  5/18/18 */
}



img.attachment-post-thumbnail.wp-post-image {
float: left;
vertical-align: top;
margin-right: 15px;
margin-top: 0px;
width: 202px;
/* height: 152px; */
}

.menu a:hover {
background-color: #fff;
background-image: none;
color: #000;
filter: none;
}

.menu a:hover {

	color: gold !important;     
} 


.menu a {
	text-transform: uppercase !important;
	color: #461d7c !important;
    font-weight: bold !important;
    font-size: 14px !important;

}

.menu a {
border-left: 0px;
cursor: pointer;
display: block;
font-size: 13px;
font-weight: normal;
height: 35px; 
line-height: 35px;
margin: 0;
padding: 0 .9em;
position: relative;
text-decoration: none;
text-shadow: none;
white-space: nowrap;
}

.menu .current_page_item a, .menu .current-menu-item a {
/* background-color: #EFEFEF; 5/18/18 */
background-color:  #9e9e9e30;
font-weight: bold;
/* border-bottom: solid 3px #fdd023; */
color: #461D7C;
 }

/* 5/18/18 */
.menu .current_page_item a, .menu .current-menu-item a, .current-menu-item a:hover, .current_page_item a:hover  {
/* background-color: transparent !important;  */
}


ul.menu > li:hover {
    background-color:transparent !important;
}


.read-more {
clear: none;
}

 .post-data {
display: none;
} 

.post-data a {
color: #461d7c;
}

body.single .post-data {
display: block;
}

.archive .post-meta {
display: none;
}

#content-archive, #content-sitemap {
    margin-top: 0px;
    margin-bottom: 20px;
}

img.attachment-full, 
img.attachment-large, 
img.attachment-medium, 
img.attachment-thumbnail, 
body.home.blog img.wp-post-image
/*img.wp-post-image */
{display: none;}

.read-more a {
color: #461d7c;
}

.post-edit {
 border-bottom: 1px solid #BEBEBE; 
clear: all !important; /* this allows the headlines to not wrap */

}

#logo {
height: 75px;
width: 400px; /* 5/18/18 */
float: left; /* 5/18/18 */
margin-left: 75px;  /* 5/18/18 */
margin-right: 10px;
background-image:url('http://news.blogs.lib.lsu.edu/files/2018/01/newbloglogo.png'); 
background-repeat:no-repeat; /* */
background-position-y: center;


}

body.custom-background {
background: #E6E6E6;
}

#logo {padding-bottom: 8px;
}

.menu {
/* background-color: #DDCC70; */
background-image: -webkit-gradient(linear, left top, left bottom, from(transparent), to(transparent));
background-image: -webkit-linear-gradient(top, transparent);
background-image: -moz-linear-gradient(top, transparent);
background-image: -ms-linear-gradient(top, transparent);
background-image: -o-linear-gradient(top,transparent);
background-image: linear-gradient(top, transparent);
clear: both;
filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=#585858, endColorstr=#3d3d3d);
margin: 0 auto;}

h1, h2, h3, h4, h5, h6, h1 a, h2 a, h3 a, h4 a, h5 a, h6 a, a  {
color: #474747;
}

h1 {
font-size: 2.0em;
}

h2, h3 {
font-size: 1.2em; 
margin-bottom: 0em;
}


.widget-title h3, .widget-title-home h3 {
text-transform: none !important;
}

/* special collections options */
/* Special Collections background color */

.archive.category.category-special-collections.category-223.custom-background, 
body.category-special-collections, .page-id-60 {
/* background-color: #6291B1;
background: #6291B1;*/
}

/*Special Collections Menu Colors */

/* body.category-special-collections .menu,  body.page-id-60  .menu {
background-color: #B9A84D; 
} */

body.category-special-collections .menu li li {
background-color: #461d7c !important;
}


body.category-special-collections .top-menu li a, body.page-id-60 .top-menu li a {
color: #eee;}

body.category-special-collections ul.menu > li:hover {
background: white;
background-color: white;
}

body.category-special-collections #logo,  body.page-id-60  #logo{
width: 400px;

/* background-image:url('http://news.blogs.lib.lsu.edu/files/2016/05/LSU-Libraries-Special-Collections.png');  */

background-image:url('http://news.blogs.lib.lsu.edu/files/2018/09/SpecialCollectionsBlogLogo.png');

background-repeat:no-repeat; 

}




body.category-special-collections #header{
background: none;
background-color: #461D7C;

}

/* making the twitter widgets show on appropriate pages */

.Hill{
display: none;
}

body.category-special-collections .Hill{
display: block;
}

body.category-special-collections .middleton{
display: none;
}

/* end of twitter widgets css */

.tiled-gallery .tiled-gallery-item a {
pointer-events: none;
cursor: default;}

.tiled-gallery-caption a {
pointer-events: auto !important;
cursor: pointer !important;

}

.widget-title h3, .widget-title-home h3 {
display: block;
font-size: 14px;
font-weight: 700;
line-height: 23px;
margin: 0;
padding: 0 0 20px;
text-align: left;
text-transform: uppercase;
}

h6.title-archive {
display: none;
}

.colophon-widget {
    background: 0 0;
    min-height: 0; 
     float: left;
margin-right: 65px;
border: none;

}

.comments-link {
Display:none;
}

body.category-special-collections .site-description {
color: #bebebe;
visibility: hidden;
}

body.category-special-collections .top-menu {
float: none; 
margin:  0; 
padding: 0;
width: 100%;
background-color: #999;
text-align: right;
}

body.category-special-collections ul.menu > li:hover {
    background-color: transparent !important;
    }

body.category-special-collections .menu a {
	color: gold !important;
    }


body.category-special-collections .menu a:hover {
	color: white !important;

    background-color:transparent !important;
    }



@media all and (min-width:1000px) {
    .main-nav {
        clear: none !important;
        float: left !important; /* not on media screen rules! */
        margin-top: 20px !important;
        margin-left: 100px !important;

}

#header {     display: inline-block;
width: 100%; }

}


@media all and (max-width: 1000px) and (min-width: 700px)  {
/* .menu li { float: none;}
.site-description { visibility: hidden;}*/

}

@media all and (max-width: 1020px)   {

.site-description { visibility: hidden;}

}


@media screen and (max-width:420px) {
#logo {

/* background-image: url('http://news.blogs.lib.lsu.edu/files/2018/01/newblogmobilelogo.png'); */
background-repeat: no-repeat;
background-position-y: center; 
}
#header {
background-color: #fff;
background: #fff;
}
}

@media screen and (max-width:970px)
{
#logo {
float:none;
margin:0;
text-align:center;
background-position-y: center; 
}

