.main-nav #responsive_current_menu_item{display:block;padding:5px 40px 5px 10px;color:#fff;font-weight:700;cursor:pointer}.js .main-nav a#responsive_menu_button{position:absolute;display:block;top:0;left:100%;height:30px;width:23px;margin-left:-30px;background:url(http://news.blogs.lib.lsu.edu/wp-content/themes/responsive/core/images/select-icons.png) 0 5px no-repeat;cursor:pointer}.js .main-nav a#responsive_menu_button.responsive-toggle-open{background:url(http://news.blogs.lib.lsu.edu/wp-content/themes/responsive/core/images/select-icons.png) 0 -46px no-repeat}.footer-menu li,.top-menu{float:none;font-size:11px;text-align:center}#author-meta{padding:20px}#wrapper .gallery .gallery-item{max-width:100%}.hide-650{display:none}.show-650{display:block}.hide-mobile{display:none}#footer{text-align:center}#footer .social-icons{padding-bottom:10px;text-align:center}} 

/* open book widget for new books posts */



span.openbook_wrapper3 {float:left; padding:5px;}

.grid.col-300.copyright, .grid.col-300.scroll-top, .grid.col-300.fit.powered  {display:none}


/* css for the event plugin widget */

.event_item {
    display: block;
    clear: both;
    font-size: .95em;
    margin: 0em 0;
    border-top: 1px dotted #808080;
}

.event_date {
    margin-bottom: 5px;
}

.event_item h5 {

    margin-top: 9px;
    line-height: 18px;

    color: #461d7c;
    font-weight: normal;
    font-size: 14px;
    text-decoration: underline;
}

a.event_link {
border: solid transparent 3px;
font-size: 12px;
font-weight: normal }

.event_data.event_category {
    display: none;
}


span.event_category {
    display: none;
}

/** CSS for calendar page, goes with the post event plugin **/
span.eventpost-date-export {
 /*   display: none; */
}


.event_date {
    margin-bottom: 13px;
}

span.linking_word.linking_word-from {
display:none;
}

.eventpost_cal_list  ul{
    list-style-type: none;
}

.eventpost_cal_list h4 {
     font-size: 1em; 
    margin-bottom: 1em;
    margin-top: 1em;
    text-align: left;
}

.event_data {background-color:none;}

.eventpost_calendar tbody button {
    padding: .3em 0;
    /* background: rgba(0,0,0,0.4); */
    /* border: #800080 1px solid; */
    width: 100%;
    background-color: #eee;
}

.eventpost_calendar button {
    cursor: pointer;
    display: inline-block;

    background: rgba(0, 0, 0, 0);
    font-weight: normal;
    box-shadow: none;
    border: 0;
    border-radius: 0;
    padding: 6px;
    color: #461d7c;
}

.eventpost_calendar tbody td.event_post_day_now {
    border: #fdd023 2px solid;
}

.eventpost_cal_list .event_date {
    margin-bottom: 30px;
    background: #fff; 
    text-align: left;
}

.eventpost_cal_list h4 {
color: #461d7c
}

.eventpost_calendar {

    border: 0px !important; 
    padding: 0em !important; 

}

.event_data.event_single {
    border-left-color: #461d7c !important;
}

@media screen and (max-width: 970px) {
 .eventpost_calendar td, th {
    padding: 0.1em;
}

.eventpost_calendar tbody button { background-color: #fff;}

}


.facultypublications
{
height: 200px;
overflow: scroll;
}

.twitterwidget
{
height: 1000px;
overflow: scroll;
}

